CREATE TABLE hr_roles(user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('hr_staff','supervisor','payroll_preparer','payroll_approver','payroll_finance')),PRIMARY KEY(user_id,role));
CREATE TABLE hr_schedules(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,weekdays TEXT NOT NULL,start_minute INTEGER NOT NULL,end_minute INTEGER NOT NULL,break_minutes INTEGER NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),CHECK(start_minute>=0 AND end_minute<=1440 AND start_minute<end_minute),CHECK(break_minutes>=0 AND break_minutes<end_minute-start_minute));
CREATE TABLE hr_holidays(id INTEGER PRIMARY KEY,schedule_id INTEGER NOT NULL REFERENCES hr_schedules(id),date TEXT NOT NULL,name TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),UNIQUE(schedule_id,date));
CREATE TABLE hr_profiles(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),effective_date TEXT NOT NULL,schedule_id INTEGER NOT NULL REFERENCES hr_schedules(id),supervisor_id INTEGER REFERENCES users(id),department TEXT NOT NULL,position TEXT NOT NULL,location TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('joining','active','transferred','departed')),private_encrypted TEXT NOT NULL,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_payment_details(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),effective_date TEXT NOT NULL,details_encrypted TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_payment_approvals(details_id INTEGER PRIMARY KEY REFERENCES hr_payment_details(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_documents(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),filename TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,content_encrypted TEXT NOT NULL,expiry TEXT,visibility TEXT NOT NULL CHECK(visibility IN('hr','employee','supervisor')),actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_attendance_reviews(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),date TEXT NOT NULL,minutes INTEGER NOT NULL CHECK(minutes BETWEEN 0 AND 1440),previous_id INTEGER REFERENCES attendance(id),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_attendance_approvals(review_id INTEGER PRIMARY KEY REFERENCES hr_attendance_reviews(id),attendance_id INTEGER NOT NULL REFERENCES attendance(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_attendance_imports(id INTEGER PRIMARY KEY,reference TEXT NOT NULL UNIQUE,rows_encrypted TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_attendance_import_posts(import_id INTEGER PRIMARY KEY REFERENCES hr_attendance_imports(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_timesheets(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),period_id INTEGER NOT NULL REFERENCES hr_periods(id),reference TEXT NOT NULL UNIQUE,creator_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL);
CREATE TABLE hr_time_lines(id INTEGER PRIMARY KEY,timesheet_id INTEGER NOT NULL REFERENCES hr_timesheets(id),date TEXT NOT NULL,start_minute INTEGER NOT NULL,end_minute INTEGER NOT NULL,project_id INTEGER NOT NULL REFERENCES projects(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),category TEXT NOT NULL,activity TEXT NOT NULL,CHECK(start_minute>=0 AND end_minute<=1440 AND start_minute<end_minute));
CREATE TABLE hr_time_approvals(timesheet_id INTEGER PRIMARY KEY REFERENCES hr_timesheets(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_time_cancellations(timesheet_id INTEGER PRIMARY KEY REFERENCES hr_timesheets(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_leave_policies(id INTEGER PRIMARY KEY,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,paid INTEGER NOT NULL CHECK(paid IN(0,1)),opening_minutes INTEGER NOT NULL,monthly_minutes INTEGER NOT NULL,carryover_cap INTEGER NOT NULL,expiry_months INTEGER NOT NULL,eligibility_days INTEGER NOT NULL,policy_state TEXT NOT NULL CHECK(policy_state IN('demo','provisional','validated')),validation_reference TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL);
CREATE TABLE hr_leave_policy_approvals(policy_id INTEGER PRIMARY KEY REFERENCES hr_leave_policies(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_leave_enrollments(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),policy_id INTEGER NOT NULL REFERENCES hr_leave_policies(id),start_date TEXT NOT NULL,opening_minutes INTEGER NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),UNIQUE(employee_id,policy_id));
CREATE TABLE hr_leave_links(request_id INTEGER PRIMARY KEY REFERENCES leave_requests(id),enrollment_id INTEGER NOT NULL REFERENCES hr_leave_enrollments(id),minutes INTEGER NOT NULL,calendar_snapshot TEXT NOT NULL);
CREATE TABLE hr_leave_cancellations(request_id INTEGER PRIMARY KEY REFERENCES leave_requests(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_periods(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,start_date TEXT NOT NULL,end_date TEXT NOT NULL,posting_date TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),CHECK(start_date<=end_date AND posting_date>=end_date));
CREATE TABLE hr_rule_status(rule_id INTEGER PRIMARY KEY REFERENCES payroll_rules(id),policy_state TEXT NOT NULL CHECK(policy_state IN('demo','provisional','validated')),validation_reference TEXT NOT NULL);
INSERT INTO hr_rule_status SELECT id,CASE WHEN demo=1 THEN 'demo' ELSE 'provisional' END,'' FROM payroll_rules;
CREATE TABLE hr_allocation_plans(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_allocation_lines(id INTEGER PRIMARY KEY,plan_id INTEGER NOT NULL REFERENCES hr_allocation_plans(id),project_id INTEGER NOT NULL REFERENCES projects(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),category TEXT NOT NULL,activity TEXT NOT NULL,weight INTEGER NOT NULL CHECK(weight>0),components TEXT NOT NULL);
CREATE TABLE hr_allocation_approvals(plan_id INTEGER PRIMARY KEY REFERENCES hr_allocation_plans(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_overtime(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),period_id INTEGER NOT NULL REFERENCES hr_periods(id),amount INTEGER NOT NULL CHECK(amount>0),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_overtime_approvals(overtime_id INTEGER PRIMARY KEY REFERENCES hr_overtime(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_salary_advances(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),project_id INTEGER NOT NULL REFERENCES projects(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),category TEXT NOT NULL,activity TEXT NOT NULL,account_id INTEGER NOT NULL REFERENCES accounts(id),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,repayment_schedule TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL);
CREATE TABLE hr_salary_advance_posts(advance_id INTEGER PRIMARY KEY REFERENCES hr_salary_advances(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE hr_salary_returns(id INTEGER PRIMARY KEY,advance_id INTEGER NOT NULL REFERENCES hr_salary_advances(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE hr_payroll_context(run_id INTEGER PRIMARY KEY REFERENCES payroll_runs(id),period_id INTEGER NOT NULL REFERENCES hr_periods(id),inputs_encrypted TEXT NOT NULL,fingerprint TEXT NOT NULL);
CREATE TABLE hr_payroll_controls(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES payroll_runs(id),allocation_id INTEGER NOT NULL REFERENCES payroll_allocations(id),account_id INTEGER NOT NULL REFERENCES accounts(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE hr_payroll_recoveries(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES payroll_runs(id),allocation_id INTEGER NOT NULL REFERENCES payroll_allocations(id),advance_id INTEGER NOT NULL REFERENCES hr_salary_advances(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE hr_payment_controls(payment_id INTEGER NOT NULL REFERENCES payroll_payments(id),allocation_id INTEGER NOT NULL REFERENCES payroll_allocations(id),account_id INTEGER NOT NULL REFERENCES accounts(id),amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,allocation_id,account_id));
CREATE TABLE hr_payment_batches(id INTEGER PRIMARY KEY,reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_batch_vouchers(batch_id INTEGER NOT NULL REFERENCES hr_payment_batches(id),voucher_id INTEGER NOT NULL UNIQUE REFERENCES vouchers(id),PRIMARY KEY(batch_id,voucher_id));
CREATE TABLE hr_batch_posts(batch_id INTEGER PRIMARY KEY REFERENCES hr_payment_batches(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE hr_batch_details(batch_id INTEGER NOT NULL REFERENCES hr_payment_batches(id),employee_id INTEGER NOT NULL REFERENCES employees(id),details_id INTEGER NOT NULL REFERENCES hr_payment_details(id),PRIMARY KEY(batch_id,employee_id));
INSERT INTO accounts(code,name,type) VALUES('1250','Employee salary advance receivable','asset'),('2120','Employee deductions and benefit remittances','payable');
